"""Deterministic bundled GEE core: repaired contracts + v0.2 engine + v4 services."""
from pathlib import Path
import hashlib
import re
import json
root=Path(__file__).resolve().parents[1]
contracts=(root/'contracts.js').read_text(encoding='utf8')
legacy=(root/'baseline/SES410_landcover_v0_2.js').read_text(encoding='utf8')
# Namespace collisions are explicit; original files remain untouched.
legacy=legacy.replace("var VERSION = '0.2.0';", "// VERSION supplied by v4 contracts")
legacy=re.sub(r'var CONFIG = \{.*?\n\};','// Effective configuration supplied solely by v4 config().',legacy,count=1,flags=re.S)
legacy=legacy.replace('function validateConfig(cfg)', 'function validateLegacyConfig(cfg)').replace('  validateConfig(cfg);','  validateLegacyConfig(cfg);').replace('exports.validateConfig = validateConfig;', 'exports.validateLegacyConfig = validateLegacyConfig;')
legacy=legacy.replace("seed: cfg.seed}).train", "seed: cfg.seed, variablesPerSplit:cfg.variablesPerSplit, minLeafPopulation:cfg.minLeafPopulation, bagFraction:cfg.bagFraction, maxNodes:cfg.maxNodes}).train")
legacy=legacy.replace('  var model = ee.Classifier', '  var fitStarted=Date.now();\n  var model = ee.Classifier')
legacy=legacy.replace('function fitAndEvaluate(', 'function legacyFitAndEvaluate(')
legacy=re.sub(r'\bfail\(', 'engineFail(', legacy)
legacy=legacy.replace('    result.completed = true;', '    result.elapsedSeconds=(Date.now()-fitStarted)/1000;\n    result.completed = true;')
legacy=legacy.replace("legend_version: 'SES410_INITIAL_2021_V1'", "legend_version: cfg.v4 ? cfg.v4.legendId : 'SES410_INITIAL_2021_V1'")
legacy=legacy.replace("status === 'REFERENCE_SAMPLE_EVALUATION'", "status !== 'PRODUCT_LABEL_PILOT_NOT_VALIDATED'")
legacy=legacy.replace('reference_n: actualN, prediction_n: predictedN,','reference_n: actualN, prediction_n: predictedN, true_positive:tp, false_positive:predictedN.subtract(tp), false_negative:actualN.subtract(tp),')
legacy=re.sub(r"classified_pixel_probe: classification.sampleRegions\(\{collection: training.limit\(1\),.*?\.aggregate_array\('classification'\)", 'raster_check_pending:true',legacy,flags=re.S)
legacy=legacy.replace(' || !report.classified_pixel_probe.length','').replace('Confusion matrix excluded observations, or raster probe was empty.','Metric count mismatch; inspect assessment IDs, masks and retained counts.')
legacy=legacy.replace("cfg.exportPrefix + ' ' + cfg.year + ' ' + status", "'EXPLORATORY DISPLAY-DEPENDENT PREVIEW '+cfg.exportPrefix + ' ' + cfg.year + ' ' + status")
legacy=legacy.replace('RUN COMPLETE: classifier and metric graphs evaluated. Full exports and scientific qualification remain separate.', 'METRICS EVALUATED: canonical all-assessment raster check follows. Preview display scale is not the canonical export grid.')
legacy=legacy.replace("cfg.seed + 1, 'pilot_holdout'","cfg.holdoutSeed, 'pilot_holdout'").replace("cfg.seed + 2, 'validation'","cfg.reservedSeed, 'validation'")
# Strict post-sampling cross-set checks replace the inherited final fit dispatch.
old="fitAndEvaluate(image, region, train, val, cfg, 'PRODUCT_LABEL_PILOT_NOT_VALIDATED');"
assert old in legacy
legacy=legacy.replace(old,"var snappedTraining=ee.Image.pixelCoordinates(grid(cfg.v4)).rename(['grid_x','grid_y']).sampleRegions({collection:train,projection:grid(cfg.v4),geometries:true}).map(function(f){return annotate(f,cfg.v4);});auditSamples(snappedTraining,val,cfg.v4,{training:s.training_n,assessment:s.drawn_validation_locations,diagnostic:true},function(a,error){if(!active(cfg))return;if(error)return engineFail(cfg,error,a);cfg.v4audit=a;fitAndEvaluate(image,region,snappedTraining,val,cfg,'PRODUCT_LABEL_PILOT_NOT_VALIDATED');});")
body=(root/'core.js').read_text(encoding='utf8')
workflow=(root/'workflow.js').read_text(encoding='utf8')
legacy=re.sub(r'^exports\.[^\n]+\n','',legacy,flags=re.M)
digest=hashlib.sha256((contracts+workflow+legacy+body).encode()).hexdigest()
def gee_ascii(text):
    # Git-backed Code Editor readers can misdecode UTF8 source; JS escapes retain
    # string semantics and make deployment bytes independent of locale.
    return ''.join(ch if ord(ch)<128 else '\\u%04x'%ord(ch) for ch in text)
app=root/'APP_HAMMER_v4.js'
app.write_text(gee_ascii(app.read_text(encoding='utf8')),encoding='utf8',newline='\n')
inputs={name:hashlib.sha256((root/name).read_text(encoding='utf8').encode('utf8')).hexdigest() for name in ['contracts.js','workflow.js','core.js','APP_HAMMER_v4.js','tools/build.py','baseline/SES410_landcover_v0_2.js']}
out='// GENERATED by tools/build.py; edit authoritative inputs, not this file.\n'+contracts+'\n'+workflow+'\n'+legacy+'\n'+body.replace('BUILD_SOURCE_HASH',digest).replace('BUILD_UI_HASH',inputs['APP_HAMMER_v4.js']).replace('BUILD_INPUT_HASHES',json.dumps(inputs,sort_keys=True))
(root/'HAMMER_CORE_v4.js').write_text(gee_ascii(out),encoding='utf8',newline='\n')
print(digest)
